import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./ViewInfo.css";

const ViewInfo = () => {
  const navigate = useNavigate();

  const images = [
    "/images/house1.jpg",
    "/images/house2.jpg",
    "/images/house3.jpg",
  ];

  const [currentImage, setCurrentImage] = useState(0);

  const nextImage = () => {
    setCurrentImage((prev) => (prev + 1) % images.length);
  };

  const prevImage = () => {
    setCurrentImage((prev) => (prev - 1 + images.length) % images.length);
  };

  return (
    <div className="property-detail">
      {/* ✅ Back Button below navbar */}
      <div className="back-button-container">
        <button className="back-button" onClick={() => navigate(-1)}>
          ← Back
        </button>
      </div>

      <div className="detail-content">
        <div className="detail-left">
          {/* ===== Image Gallery ===== */}
          <div className="image-gallery">
            <div className="main-image-container">
              <button className="nav-arrow left" onClick={prevImage}>
                ❮
              </button>
              <img
                src={images[currentImage]}
                alt="Property"
                className="main-image"
              />
              <button className="nav-arrow right" onClick={nextImage}>
                ❯
              </button>
              <div className="image-counter">
                {currentImage + 1}/{images.length}
              </div>
            </div>

            <div className="thumbnail-container">
              {images.map((img, index) => (
                <img
                  key={index}
                  src={img}
                  alt={`Thumbnail ${index + 1}`}
                  className={`thumbnail ${
                    currentImage === index ? "active" : ""
                  }`}
                  onClick={() => setCurrentImage(index)}
                />
              ))}
            </div>
          </div>

          {/* ===== Property Info ===== */}
          <h2 className="property-title">Cozy Apartment in the City</h2>
          <p className="property-location">Manila, Philippines</p>
          <p className="property-price">₱25,000 / month</p>

          {/* ===== Highlights ===== */}
          <div className="highlights-section">
            <h3>Highlights</h3>
            <div className="highlights-grid">
              <span className="highlight-badge">2 Bedrooms</span>
              <span className="highlight-badge">1 Bathroom</span>
              <span className="highlight-badge">Fully Furnished</span>
              <span className="highlight-badge">Near Transportation</span>
            </div>
          </div>

          {/* ===== Details ===== */}
          <div className="details-section">
            <h3>Details</h3>
            <h4>Description</h4>
            <p>
              This modern apartment offers a comfortable living space with
              excellent natural lighting. Conveniently located near restaurants
              and schools.
            </p>
            <h4>Features</h4>
            <ul>
              <li>Air conditioning</li>
              <li>High-speed Wi-Fi</li>
              <li>Parking space</li>
            </ul>
          </div>

          {/* ===== Contact ===== */}
          <div className="contact-card">
            <h3>Contact the Landlord</h3>
            <div className="contact-info">
              <input type="text" placeholder="Your Name" />
              <input type="email" placeholder="Your Email" />
              <input type="text" placeholder="Your Message" />
            </div>
            <div className="update-info">📞 +63 912 345 6789</div>
          </div>

          {/* ===== Location ===== */}
          <div className="location-card">
            <h3>Location</h3>
            <div className="map-placeholder">Map Placeholder</div>
          </div>

          {/* ===== Rent Button ===== */}
          <button
            className="rent-button"
            onClick={() => navigate("/rentpage")}
          >
            Rent Now
          </button>
        </div>
      </div>
    </div>
  );
};

export default ViewInfo;
